#include "FreeRTOSConfig.h"
#include "task.h"

/* Demo includes. */
#include "mpu_demo.h"

#include <stdint.h>

/** ARMv7 MPU Details:
 *
 * - ARMv7 MPU requires that the size of a MPU region is a power of 2.
