     * fault. A cleared tracker confirms the write to RO memory was rejected. */
    xWriteRejected = prvAttemptWriteExpectingMPUFault();
    prvReportSafetyCheck( xWriteRejected, SP1_PASS_MESSAGE, SP1_FAIL_MESSAGE );
}
